  CONSTRAINT `fk_tarjeta_debito_tarjeta` FOREIGN KEY (`idtarjeta`) REFERENCES `tarjeta` (`id`),
  CONSTRAINT `fk_tarjeta_debito_tarjeta_credito` FOREIGN KEY (`idtarjeta_credito`) REFERENCES `tarjeta_credito` (`id`)
